sys_script_client.script:
function onLoad() {
   //Type appropriate comment here, and begin script below

   var trigger_by = g_scratchpad.triggerby;
	var code = trigger_by.slice(0,2);
	if(code=='MT'){
		g_form.setDisplay('tran_reference_for_swift_linking',true);
		g_form.setDisplay('swift_linking_reference_id',true);
		g_form.setDisplay('swift_linking_reference',true);  	//Added as part of MSSCUSTODY-3122
	}
	else{
		g_form.setMandatory('tran_reference_for_swift_linking',false);
		g_form.setDisplay('tran_reference_for_swift_linking',false);
		g_form.setMandatory('swift_linking_reference_id',false);
		g_form.setDisplay('swift_linking_reference_id',false);
		g_form.setDisplay('swift_linking_reference',false);  	//Added as part of MSSCUSTODY-3122.
	}


}
